def the_discipline_retold(case, data):
    """F1 — Deut 11:1-7: love and keep (11:1 — demand_declared by kind, VARIANT); the discipline seen (11:2 — the noun's one Torah seat; GL by CALL); signs and deeds (11:3 — plague_struck TEN by kind); the sea flowed over them (11:4 — sea_returned by kind, the hiphil's one seat); the wilderness (11:5 — THE STATE ROW, SUPPLIED with no write); Dathan and Abiram (11:6 — earth_swallowed by kind, KR and SC by CALL); KORAH UNNAMED (the tape already reads the verse as the chapter does); every living thing (the flood's word — PR by CALL); your eyes have seen (11:7 — SN by CALL; Joshua's and Judges' epilogue read from it)"""
    del P_[:]
    ask = case['ask']
    if ask == 'love_and_keep':
        ink('11:1', '"AND YOU SHALL LOVE the LORD your God AND KEEP HIS CHARGE, His statutes, His judgments and His commandments always" — "and you shall love the LORD your God" the two seats %s; "and you shall love" the Torah\'s four %s; "keep His charge" the ONE SEAT %s (Numbers 3:7 the priests\' "his charge" the lemma\'s other form); the four nouns the book\'s form; the register SINGULAR %s; the shared run with 30:16 %d, 6:5 %d' % (P('ואהבת', 'את', 'יהוה', 'אלהיך'), U('ואהבת', books=T), P('ושמרת', 'משמרתו'), NUM[1], SH(D11(1), ('Deut', 30, 16)), SH(D11(1), ('Deut', 6, 5))))
        move('cold_run_second_tablets (CALL) — ST.what_the_lord_asks(what_does_the_lord_ask) = %s; cold_run_hear_o_israel (CALL) — HI.the_creed(love_and_fear) = %s' % (ST_ASK[0][:60], HI_LOVE[0][:60]), "10:12's five infinitives (demand_declared on the tape at Deut 10:12 — fear_of_heaven_asked on Israel UNMOVED) and 6:5's creed (shema_commanded on Israel UNMOVED): the readback row 11:1 VARIANT by kind against demand_declared — 'His charge' the book's one seat")
        dat('the readback row 11:1 — VARIANT (demand_declared Deut 10:12 by kind and first verse); Onkelos "ותרחם ית יי אלהך" (and you shall love the LORD your God) with the Word\'s charge; a DATA row: "His charge" the book\'s one seat')
        return out("love and keep (11:1) — 10:12's five infinitives and 6:5's creed said again with 'His charge' the book's one seat (Numbers 3:7 the priests'): the readback row VARIANT against demand_declared (Deut 10:12) by kind; no write", ['accepted'])
    if ask == 'the_discipline_seen':
        ink('11:2', '"and know today — not your children who have not known and have not seen THE DISCIPLINE of the LORD your God" — the noun "discipline" the Torah\'s ONE SEAT %s (fifty in the Bible, Proverbs\' word — "the discipline of the LORD" 11:2 and Proverbs 3:11 %s); "His greatness, His strong hand and His outstretched arm" the one seat of the pair %s; the three "not"s %s; the shared run with 31:13 %d, 8:5 %d' % ([(s, x) for s, x, _ in LEMT('4148', books=T)], P('מוסר', 'יהוה'), P('ידו', 'החזקה', 'וזרעו', 'הנטויה'), [x for x in W11(2) if x in NEG], SH(D11(2), ('Deut', 31, 13)), SH(D11(2), ('Deut', 8, 5))))
        move('cold_run_good_land (CALL) — GL.the_way_of_forty_years(the_discipline) = %s; cold_run_second_census (CALL) — SC.the_roll(hu_dathan) = %s' % (GL_DISC[0][:70], SC_HU[0][:50]), "8:5's 'as a man disciplines his son' the discipline's verb (the Land acquired through suffering — Berakhot 5a); the children who have not known the second census's own generation (the roll after the plague, 26:64-65 — none of the counted at Sinai)")
        dat('the readback row 11:2 — VARIANT by CALL (GL.the_way_of_forty_years); "not your children" the generation the census counts — a DATA row; Onkelos "ית אולפנא דיי" (the instruction of the LORD)')
        return out("the discipline seen (11:2) — 'the discipline of the LORD' the noun's one Torah seat (Proverbs 3:11 its kin), 8:5's verb by CALL (GL.the_way_of_forty_years): the readback row VARIANT; the children who have not known the census's generation (SC by CALL)", ['accepted'])
    if ask == 'signs_and_deeds':
        ink('11:3', '"His SIGNS and His DEEDS which He did in the midst of Egypt to Pharaoh king of Egypt and to all his land" — "His signs and His deeds" the one seat %s; "in the midst of Egypt" the two seats %s (Exodus 11:4 the firstborn\'s night); "to Pharaoh king of Egypt and to all his land" the one seat %s; the shared run with 29:1 %d, 34:11 %d' % (P('אתתיו', 'ואת', 'מעשיו'), P('בתוך', 'מצרים'), P('לפרעה', 'מלך', 'מצרים', 'ולכל', 'ארצו'), SH(D11(3), ('Deut', 29, 1)), SH(D11(3), ('Deut', 34, 11))))
        move('cold_run_exodus_story (CALL) — ES.plagues(ten) = %s' % (ES_PLAGUES['v'],), "Mishnah Avot 5:4's ten plagues — the tape's plague_struck TEN (Exodus 7:20, 8:2, 8:13, 8:20, 9:6, 9:10, 9:23, 10:13, 10:22, 12:29 — each a HEAVEN entry on Egypt), the firstborn's at 12:29 under the marker M['exodus']: the readback row 11:3 VERBATIM in kind against plague_struck (Exod 12:29) by kind and first verse")
        dat('the readback row 11:3 — VERBATIM in kind (plague_struck Exod 12:29 by kind and first verse; the ten lines DC7); Onkelos "ית אתותיה וית עובדוהי" (His signs and His deeds)')
        return out("signs and deeds (11:3) — the plagues' ten lines on the tape (plague_struck Exod 7:20 through 12:29; ES.plagues('ten') = 10 by CALL): the readback row VERBATIM in kind against plague_struck (Exod 12:29); 'to Pharaoh king of Egypt and to all his land' the one seat", ['accepted'])
    if ask == 'the_sea_flowed':
        ink('11:4', '"what He did to the army of Egypt, to its horses and to its chariots, over whom HE MADE THE WATERS OF THE RED SEA FLOW as they pursued you, and the LORD destroyed them TO THIS DAY" — "made flow" the hiphil perfect\'s ONE SEAT %s (the lemma\'s three Bible seats); "the waters of the Red Sea" the two seats %s (Joshua 2:10 Rahab\'s — THE RUN\'S RECEIPT); "as they pursued you" the one seat %s; "to this day" the book\'s six; the shared run with 34:6 %d, Joshua 24:6 %d' % ([(s, x, m) for s, x, m in LEMT('6687')], P('מי', 'ים', 'סוף'), P('ברדפם', 'אחריכם'), SH(D11(4), ('Deut', 34, 6)), SH(D11(4), ('Josh', 24, 6))))
        move('cold_run_exodus_story (CALL) — ES.sea(saved_seat) = %s; ES.sea(ten_at_sea) = %s; ES.sea(song_mode) = %s' % (ES_SAVED['v'], ES_TEN['v'], ES_SONG['v']), "the tape's sea — pursued (14:8-9, egypt_people), sea_split (14:21 under M['sea']), sea_returned (14:27-28 with egypt_drowned the DESTROY on Pharaoh's host), saved_at_the_sea (14:30 — the verb's one Torah seat), the song (15:1): the readback row 11:4 VERBATIM in kind against sea_returned (Exod 14:27) by kind and first verse — THE VERB TURNED ('made flow' for 'returned'); ten miracles at the sea (Mishnah Avot 5:4)")
        dat('the readback row 11:4 — VERBATIM in kind (sea_returned Exod 14:27 by kind; egypt_drowned ONE on Pharaoh\'s host — DC7); Rahab\'s "the waters of the Red Sea" (Joshua 2:10; Tosefta Sotah 8:2) the run\'s receipt — a DATA row; Onkelos "דאטיף ית מי ימא דסוף" (that He made the waters of the Red Sea flow)')
        return out("the sea flowed over them (11:4) — sea_returned (Exod 14:27-28) by kind with egypt_drowned the DESTROY on Pharaoh's host (ES.sea by CALL — saved at 14:30, ten miracles): the readback row VERBATIM in kind, the verb TURNED ('made flow' the hiphil's one seat); 'to this day' the run's stamp, Rahab's receipt (Joshua 2:10)", ['accepted'])
    if ask == 'the_wilderness_state':
        ink('11:5', '"and what He did for you in the wilderness UNTIL YOU CAME TO THIS PLACE" — the clause\'s three seats %s (1:31 the carrying, 9:7 the rebelling, 11:5 the doing); "in the wilderness" the book\'s nine; the register PLURAL %s; the shared run with 9:7 %d, 1:31 %d' % (P('עד', 'באכם', 'עד', 'המקום', 'הזה'), NUM[5], SH(D11(5), ('Deut', 9, 7)), SH(D11(5), ('Deut', 1, 31))))
        move('cold_run_good_land (CALL) — GL.the_way_of_forty_years(forty_years) = %s; cold_run_not_righteousness (CALL) — NR.the_frame(nations_greater) = %s' % (GL_FORTY[0][:60], NR_GREATER[0][:50]), "8:2-4's forty years as a STATE (the garment that did not wear out — chapter 8's fifth form: SUPPLIED, no write, no day) and 9:7's 'from the day you went out of Egypt until you came to this place': THE STATE ROW 11:5 — a forty-year condition with no day, no line, no write (the one database on Israel %r)" % (RAIN_SCAN,))
        dat('the readback row 11:5 — SUPPLIED with NO write (chapter 8\'s decision reused unchanged — the owner\'s word standing open); the manna, the rock and the serpents have lines, the wilderness\'s doing as a whole none; Onkelos "עד מיתיכון עד אתרא הדין" (until your coming to this place)')
        return out("the wilderness (11:5) — 'what He did for you in the wilderness until you came to this place' (the clause's three seats — 1:31, 9:7, 11:5): THE STATE ROW, SUPPLIED with no write (chapter 8's fifth form — GL.the_way_of_forty_years by CALL); no day, no line, no write", ['accepted'])
    if ask == 'dathan_and_abiram':
        ink('11:6', '"and what He did to DATHAN AND ABIRAM, sons of Eliab son of Reuben — how THE EARTH OPENED ITS MOUTH and swallowed them, their households, their tents and every living thing at their feet, in the midst of all Israel" — Dathan and Abiram\'s eight Bible seats %s (Psalm 106:17 the run\'s); "sons of Eliab" %s; "the earth opened its mouth" the retelling\'s own form %s against Numbers 16:32\'s and 26:10\'s "and the earth opened its mouth" %s and 16:30\'s "the ground" %s; "and their households" the two seats %s, "and their tents" the ONE %s; the shared run with 16:32 %d' % (U('דתן', 'לדתן', 'ודתן'), P('בני', 'אליאב'), P('פצתה', 'הארץ', 'את', 'פיה'), P('ותפתח', 'הארץ', 'את', 'פיה'), P('ופצתה', 'האדמה', 'את', 'פיה'), P('ואת', 'בתיהם'), P('ואת', 'אהליהם'), SH(D11(6), ('Num', 16, 32))))
        move('cold_run_korach (CALL) — KR.rebellion(swallowed) = %s; cold_run_second_census (CALL) — SC.the_roll(hu_dathan) = %s; SC.the_roll(korach_recalled) = %s' % (KR_SWAL[0][:70], SC_HU[0][:50], SC_REC[0][:50]), "the tape's earth_swallowed (Num 16:31-34 — subject dathan; swallowed ['dathan', 'abiram', 'their households', 'every person who belonged to Korach']; korach_named False): the readback row 11:6 VARIANT by kind and first verse — 'their tents and every living thing at their feet' for 'every person who belonged to Korach'; 26:9-11's 'this is Dathan and Abiram' the same from beginning to end")
        dat('the readback row 11:6 — VARIANT (earth_swallowed Num 16:31 by kind; DC7 the swallowed list the tape\'s four, korach_named False); Onkelos "ית דתן ואבירם" (Dathan and Abiram)')
        return out("Dathan and Abiram (11:6) — earth_swallowed (Num 16:31-34) by kind: the readback row VARIANT (the tape's 'their households' and 'every person who belonged to Korach' against the retelling's 'their tents and every living thing at their feet'); KR.rebellion('swallowed') and SC.the_roll('hu_dathan') by CALL — the same from beginning to end", ['accepted'])
    if ask == 'korah_unnamed':
        ink('11:6', '"Dathan and Abiram" — KORAH UNNAMED in the retelling: the token "Korah" in the chapter %s (Numbers 16:32 "all the men who belonged to Korach", 26:10 "and Korach", Psalm 106:17 Dathan and Abiram alone); "the sustenance at their feet" %s the one seat' % ([v for v in range(1, 33) for x in W11(v) if x in ('קרח', 'וקרח', 'לקרח')], P('היקום', 'אשר', 'ברגליהם')))
        move('cold_run_korach (CALL) — KR.rebellion(death_mode) = %s; KR.rebellion(names) = %s' % (KR_MODE[0][:80], KR_NAMES[0][:50]), "THE TAPE ALREADY READS THE VERSE AS THE CHAPTER DOES — earth_swallowed's korach_named False (the Korah compile's reading of 16:32: the men who belonged to Korach, not Korach), Korah's death mode the cell's OPEN row (R. Yochanan the plague; the baraita burned and swallowed — Sanhedrin 110a); Korah's wealth 'the sustenance at their feet' (Pesachim 119a:12 — Reish Lakish's riches kept to his hurt; R. Levi's three hundred mules of keys; Sanhedrin 110a:11 credited): the exam's person the one who names Korah at the swallowing — accepted against")
        dat('Korah unnamed on both — the retelling and the tape (korach_named False asserted at DC7; the design\'s measurement); a DATA row; the exam\'s person accepted against')
        return out("Korah unnamed (11:6) — the retelling names Dathan and Abiram alone, and the tape's earth_swallowed already reads 16:32 so (korach_named False — the Korah compile): the one who names Korah at the swallowing accepted against; Korah's death mode the cell's OPEN row (KR.rebellion('death_mode') by CALL); his wealth 'the sustenance at their feet' (Pesachim 119a:12)", ['accepted'])
    if ask == 'every_living_thing':
        ink('11:6', '"and EVERY LIVING THING at their feet" — the lemma\'s THREE Bible seats %s (Genesis 7:4 "every living thing that I have made", 7:23 "every living thing was wiped out" — the flood\'s word); "in the midst of all Israel" %s' % ([(s, x) for s, x, _ in LEMT('3351')], P('בקרב', 'כל', 'ישראל')))
        move('cold_run_primeval (CALL) — PR.flood(remnant) = %s' % (PR_REM['v'],), "the tape's all_flesh_expired (Gen 7:21-23 — the generation of the flood; the close to_be_wiped 'and He wiped out every living thing'): the retelling's word for the swallowed the flood's — a DATA row by the ink; Sanhedrin 37b's 'the ground opened its mouth' for Abel and for Korah (KR.rebellion('earth_mouth_cain') by CALL)")
        dat('"every living thing" the flood\'s word at the swallowing — a DATA row (all_flesh_expired Gen 7:21 by kind, DC7 ONE); KR.rebellion(earth_mouth_cain) = %s' % (KR_CAIN[0][:60],))
        return out("every living thing (11:6) — the flood's word (the lemma's three Bible seats: Genesis 7:4, 7:23, Deut 11:6) at the swallowing: all_flesh_expired (Gen 7:21-23) by kind, PR.flood('remnant') by CALL; the earth's mouth for Abel and for Korah (Sanhedrin 37b — KR by CALL): a DATA row", ['accepted'])
    if ask == 'your_eyes_have_seen':
        ink('11:7', '"for YOUR EYES HAVE SEEN every great deed of the LORD which He did" — "your eyes have seen" plural the two seats %s (4:3 Baal-peor\'s), singular 3:21; "every deed of the LORD" the three seats %s — JOSHUA 24:31 AND JUDGES 2:7 read the elders\' generation from this verse ("who had known every deed of the LORD which He did for Israel"); the shared run with Judges 2:7 %d, Joshua 24:31 %d' % (P('עיניכם', 'הראת'), P('כל', 'מעשה', 'יהוה'), SH(D11(7), ('Judg', 2, 7)), SH(D11(7), ('Josh', 24, 31))))
        move('cold_run_seven_nations (CALL) — SN.do_not_fear(the_trials) = %s' % (SN_TRIALS[0][:70],), "7:19's 'the great trials which your eyes saw' (4:34's list read back — ES and OH by CALL at chapter 7): the readback row 11:7 VARIANT by CALL; Joshua 24:31 and Judges 2:7 THE RUN'S SENTENCE — the elders who outlived Joshua 'had known every deed of the LORD'; Shabbat 105b:11's 'many days, not years'")
        dat('the readback row 11:7 — VARIANT by CALL (SN.do_not_fear); the run\'s sentence Joshua 24:31 / Judges 2:7 a DATA row; Onkelos "ארי עיניכון חזאה" (for your eyes have seen)')
        return out("your eyes have seen (11:7) — 7:19's trials by CALL (SN.do_not_fear): the readback row VARIANT; 'every deed of the LORD' the three seats — Joshua 24:31 and Judges 2:7 the run's sentence on the elders' generation (a DATA row)", ['accepted'])
    return out('no verdict in span', [FX.NONE])


def the_land_watered_by_heaven(case, data):
    """F2 — Deut 11:8-12: all the commandment (11:8 = 8:1 twelve tokens — GL by CALL, VERBATIM in kind); the oath to the fathers (11:9 — GL, HI by CALL; 'swore' no number); not like Egypt (11:10 — lot_chose by kind; the foot a handbreadth, Shabbat 85a:3); drinks by the rain of heaven (11:11 — the source of rain a DISPUTE, Ta'anit 9b:10-11); the Land watered first (Ta'anit 10a:2-3 — THE CROWN); the eyes from the year's beginning (11:12 — the year judged at its head); THE DECREE AND THE SEASON (Rosh Hashanah 17b:11-13 — 'in its season' the free variable after the decree: rain_in_its_season's value)"""
    del P_[:]
    ask = case['ask']
    if ask == 'all_the_commandment':
        ink('11:8', '"and you shall keep ALL THE COMMANDMENT which I command you this day, that you may be strong and go in and possess the land" — "all the commandment" the book\'s seven %s; "that you may be strong" the one seat with Ezra 9:12 %s; "and you shall go in and possess the land" %s; the shared run with 8:1 %d (TWELVE — the frame\'s pair), 4:1 %d' % (P('את', 'כל', 'המצוה', books=('Deut',)), P('למען', 'תחזקו'), P('ובאתם', 'וירשתם', 'את', 'הארץ'), SH(D11(8), ('Deut', 8, 1)), SH(D11(8), ('Deut', 4, 1))))
        move('cold_run_good_land (CALL) — GL.the_frame(all_the_commandment) = %s; GL.the_frame(live_and_possess) = %s' % (GL_ALL[0][:60], GL_LIVE[0][:60]), "8:1's frame ('all the commandment which I command you this day … that you may live and multiply and go in and possess the land') — 11:8 the same frame twelve tokens shared: the readback row VERBATIM in kind by CALL; 4:1, 8:1, 11:8 the clause's three seats")
        dat('the readback row 11:8 — VERBATIM in kind by CALL (GL.the_frame); "that you may be strong" the one seat with Ezra 9:12 — a DATA row; Onkelos "ותטרון ית כל תפקדתא" (and you shall keep all the commandment)')
        return out("all the commandment (11:8) — 8:1's frame twelve tokens shared (GL.the_frame by CALL — 4:1, 8:1, 11:8 the three seats): the readback row VERBATIM in kind; 'that you may be strong' the one seat with Ezra 9:12", ['accepted'])
    if ask == 'the_oath_to_the_fathers':
        ink('11:9', '"and that you may prolong days on the land which the LORD SWORE to your fathers to give to them and to their seed, a land flowing with milk and honey" — "on the land which the LORD swore to your fathers" the two seats %s (11:9, 11:21); "swore" no number to the parser (the seven-stem homograph — NUMS %s); "flowing with milk and honey" fourteen in the Bible, DATHAN AND ABIRAM\'S OWN WORDS said of Egypt (Numbers 16:13) and denied of Canaan (16:14) %s; the shared run with Joshua 5:6 %d' % (P('על', 'האדמה', 'אשר', 'נשבע', 'יהוה', 'לאבתיכם'), NUMS[9], (words('Num', 16, 13)[3:7], words('Num', 16, 14)[3:7]), SH(D11(9), ('Josh', 5, 6))))
        move('cold_run_good_land (CALL) — GL.the_frame(the_oath_seats) = %s; cold_run_hear_o_israel (CALL) — HI.the_header(the_land_flowing) = %s' % (GL_OATH[0][:60], HI_LAND[0][:60]), "the oath's lines on the tape (sworn_by_himself Gen 22:16 by kind — 7:8's, 9:5's form) and 6:3's first 'milk and honey' in the book: the readback row 11:9 VARIANT by CALL; 'to them and to their seed' the resurrection's seat at 11:21 (the Sifrei 47:2; Sanhedrin 90b:12 credited)")
        dat('the readback row 11:9 — VARIANT by CALL (GL.the_frame, HI.the_header); "to give to them" the resurrection\'s word at 11:21 — a DATA row; Dathan and Abiram\'s "milk and honey" of Egypt (Numbers 16:13) the docket\'s and the reading\'s find; Onkelos "ארע עבדא חלב ודבש" (a land making milk and honey)')
        return out("the oath to the fathers (11:9) — the oath's seats (GL.the_frame('the_oath_seats') by CALL; sworn_by_himself Gen 22:16 by kind) and 6:3's milk and honey (HI.the_header by CALL): the readback row VARIANT; 'to them and to their seed' the resurrection's seat forward (11:21); 'swore' no number", ['accepted'])
    if ask == 'not_like_egypt':
        ink('11:10', '"for the land which you are entering to possess is NOT LIKE THE LAND OF EGYPT from which you came out, where you sowed your seed and WATERED IT WITH YOUR FOOT, like a garden of herbs" — "like the land of Egypt" the two seats %s (Genesis 13:10 LOT\'S CLAUSE — "like the garden of the LORD, like the land of Egypt" %s); "like a garden of herbs" the one seat %s; "and watered it with your foot" the one seat %s; "garden" the lemma\'s fifteen Torah seats, this the one outside Genesis %s; the shared run with Genesis 13:10 %d' % (P('כארץ', 'מצרים'), P('כגן', 'יהוה', 'כארץ', 'מצרים'), P('כגן', 'הירק'), P('והשקית', 'ברגלך'), [(s, x) for s, x, _ in LEMT('1588', books=T)][0], SH(D11(10), ('Gen', 13, 10))))
        move('Shabbat 85a:3 (read whole at the docket); Ta\'anit 10a:9-10', "THE GARDEN BED'S BORDER A FOOT'S WIDTH — R. Zeira (or R. Chanina bar Pappa) for R. Yehuda: 'and you watered it with your foot like a garden of herbs' (11:10) — as the foot is a handbreadth wide, so the border between beds where one walks to water: 11:10's Egypt clause read for a MEASURE; Egypt four hundred by four hundred parasangs (10a:9); Babylonia rich without rain, Egypt's likeness (10a:10)")
        dat('the readback row 11:10 — EXPANDED (lot_chose Gen 13:10 by kind — Lot\'s "like the land of Egypt"; the comparison with Egypt the retelling\'s own); the foot a handbreadth a DATA row the design did not predict; the exam\'s person the one who measures the garden bed by the foot — accepted; Onkelos "ומשקי לה ברגלך" (and you watered it with your foot)')
        return out("not like Egypt (11:10) — Lot's clause 'like the land of Egypt' (Genesis 13:10 — lot_chose by kind): the readback row EXPANDED; 'watered it with your foot' read for a measure — the garden bed's border a handbreadth (Shabbat 85a:3): the one who measures the bed by the foot accepted", ['accepted'])
    if ask == 'drinks_by_the_rain_of_heaven':
        ink('11:11', '"but the land which you are crossing over to possess is a land of hills and valleys; BY THE RAIN OF HEAVEN IT DRINKS WATER" — "a land of hills and valleys" the one seat %s (8:7 "in the valley and in the hill" the pair reversed %s); "by the rain of heaven it drinks water" the one seat %s; "rain" the lemma\'s Torah seats %s; "drinks water" the two seats %s (1 Kings 13:9 the man of God\'s); the shared run with 8:7 %d' % (P('ארץ', 'הרים', 'ובקעת'), P('בבקעה', 'ובהר'), P('למטר', 'השמים', 'תשתה', 'מים'), [(s, x) for s, x, _ in LEMT('4306', books=T)], P('תשתה', 'מים'), SH(D11(11), ('Deut', 8, 7))))
        move('Ta\'anit 9b:10-11, 9b:14-16, 10a:4-7 (read whole at the docket); Bava Batra 19a:18', "THE SOURCE OF RAIN A DISPUTE — R. Eliezer: the whole world drinks from the ocean's waters, sweetened in the clouds (Genesis 2:6's mist; 'darkness of waters' / 'gathering of waters' the two verses' one letter); R. YEHOSHUA: FROM THE UPPER WATERS — 'BY THE RAIN OF HEAVEN IT DRINKS WATER' (11:11) HIS VERSE, the clouds rising to receive it (Job 36:27); no water channels needed in the Land — the mishna's plow distanced for seeds, not for channels (Bava Batra 19a:18)")
        move('cold_run_good_land (CALL) — GL.the_good_land(the_good_land) = %s' % (GL_GOOD[0][:60],), "8:7-10's praise of the land (the waters, the seven species) — 11:11's praise its kin: the readback row EXPANDED by CALL")
